 "content": "def transform(grid):
    """Copy the non-background pattern into every panel separated by solid lines."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Solid full-width/full-height lines in a non-background color are panel dividers.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Use the panel containing the most non-background cells as the source pattern.
    panels = []
    for r0, r1 in row_panels:
        for c0, c1 in col_panels:
            score = sum(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1))
            panels.append((score, r0, r1, c0, c1))
    _, sr0, sr1, sc0, sc1 = max(panels)
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in row_panels:
        for c0, c1 in col_panels:
            if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
                continue
            for dr, r in enumerate(range(r0, r1)):
                for dc, c in enumerate(range(c0, c1)):
                    out[r][c] = pattern[dr][dc]
    return out
